insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('course-pdfs','course-pdfs',false,15728640,array['application/pdf']) on conflict(id) do nothing;
create policy pdf_insert on storage.objects for insert to authenticated with check(bucket_id='course-pdfs' and exists(select 1 from public.resources r where r.author_id=auth.uid() and r.status='pending' and r.source_kind='pdf' and r.storage_path=name));
create policy pdf_owner_read on storage.objects for select to authenticated using(bucket_id='course-pdfs' and exists(select 1 from public.resources r where r.storage_path=name and (r.author_id=auth.uid() or r.status='published' or public.is_moderator())));
create policy pdf_owner_delete on storage.objects for delete to authenticated using(bucket_id='course-pdfs' and exists(select 1 from public.resources r where r.storage_path=name and r.author_id=auth.uid() and r.status='pending'));
create function public.prepare_pdf(p_course uuid,p_topic uuid,p_title text,p_description text,p_type text,p_rights boolean,p_ai boolean default false) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('pdf',10);rid uuid:=gen_random_uuid();begin
 if not p_rights or not exists(select 1 from public.courses where id=p_course and is_active) then raise exception 'invalid context or rights';end if;
 insert into public.resources(id,course_id,topic_id,author_id,title,description,type,source_kind,storage_path,rights_confirmed,is_ai_assisted,status) values(rid,p_course,p_topic,actor,p_title,p_description,p_type,'pdf',actor::text||'/'||rid::text||'.pdf',true,p_ai,'pending');return rid;end;$$;
create function public.finalize_pdf(p_resource uuid) returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=public.require_actor('finalize',30);r public.resources;begin
 select * into r from public.resources where id=p_resource and author_id=actor and source_kind='pdf' and status='pending' for update;if not found then raise exception 'upload unavailable';end if;
 if not exists(select 1 from storage.objects where bucket_id='course-pdfs' and name=r.storage_path and (metadata->>'size')::bigint between 5 and 15728640 and metadata->>'mimetype'='application/pdf') then raise exception 'file missing or invalid';end if;
 update public.resources set status='published',updated_at=now() where id=p_resource;insert into public.product_events(event,actor_id,course_id,resource_id) values('resource_submitted',actor,r.course_id,p_resource);end;$$;
-- Mint anonymous PDF links only after a published-resource check. Storage objects remain private.
create function public.published_pdf_path(p_resource uuid) returns text language sql stable security definer set search_path='' as $$select r.storage_path from public.resources r join public.courses c on c.id=r.course_id where r.id=p_resource and r.status='published' and r.source_kind='pdf' and c.is_active;$$;
revoke all on function public.prepare_pdf(uuid,uuid,text,text,text,boolean,boolean),public.finalize_pdf(uuid),public.published_pdf_path(uuid) from public,anon,authenticated;
grant execute on function public.prepare_pdf(uuid,uuid,text,text,text,boolean,boolean),public.finalize_pdf(uuid) to authenticated;
-- Anonymous signing requires a dedicated route with server-only service credentials. The application
-- streams published PDF bytes via a narrow SQL path + a server-only storage client instead.
